"""Setup check for the astronomy workbench: interpreter, pinned libraries, offline data folders, a seeded sky.

python check_env.py
"""
import importlib.metadata as md
import platform
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
DATA = HERE.parents[1] / "data"  # labs/data: raw (never edited), cache (safe to delete), derived (re-creatable)
FOLDERS = ("raw", "cache", "derived")


def parse_pins(text):
    # splitlines + strip: the file may have Windows CRLF line endings after a git checkout
    return dict(line.strip().split("==") for line in text.splitlines() if line.strip() and not line.startswith("#"))


PINS = parse_pins((HERE / "requirements.txt").read_text(encoding="utf-8"))


def installed(pkg):
    try:
        return md.version(pkg)
    except md.PackageNotFoundError:
        return None


def make_folders(root=DATA):
    for name in FOLDERS:
        (root / name).mkdir(parents=True, exist_ok=True)  # offline-first: every lab reads/writes here, no network
    return [str((root / n).relative_to(root.parent)) for n in FOLDERS]


def synthetic_stars(seed, n=3):
    import numpy as np
    rng = np.random.default_rng(seed)  # seeded: the same "random" star field on every machine
    ra = rng.uniform(0, 360, n).round(4)
    mag = rng.uniform(2, 12, n).round(2)
    return list(zip(ra.tolist(), mag.tolist()))


def main():
    print(f"Python {platform.python_version()} on {platform.system()} {platform.machine()}")
    ok = sys.version_info >= (3, 12)
    for pkg, pin in PINS.items():
        have = installed(pkg)
        where = "local" if pkg == "numpy" else "CI"
        status = f"installed {have}" + ("" if have == pin else f" (pin {pin})") if have else f"not installed -> runs in {where}"
        print(f"  {pkg:<9} pin {pin:<7} {status}")
        ok &= bool(have) or pkg != "numpy"  # numpy is the only package the local labs need
    print("data folders:", ", ".join(make_folders()))
    print("seed 42 stars (RA deg, mag):", synthetic_stars(42))
    print("READY for local labs" if ok else "NOT READY: need Python 3.12+ and numpy")


if __name__ == "__main__":
    main()

"""L100 Units and scales: AU, light-year, parsec, magnitudes <-> flux, distance modulus.

python units.py
"""
import math

C = 299_792_458.0                 # speed of light, m/s (exact, SI)
AU = 149_597_870_700.0            # astronomical unit, m (exact, IAU 2012 Resolution B2)
JULIAN_YEAR = 365.25 * 86_400.0   # s (IAU: the light-year uses the Julian year)
LY = C * JULIAN_YEAR              # light-year, m
PC = AU * 648_000.0 / math.pi     # parsec: distance at which 1 AU subtends 1 arcsecond (IAU 2015 Resolution B2)


def flux_ratio(m1, m2):
    """F1/F2 for magnitudes m1, m2 (Pogson: 5 magnitudes = factor 100; brighter = smaller magnitude)."""
    return 10 ** (-0.4 * (m1 - m2))


def mag_difference(f1, f2):
    return -2.5 * math.log10(f1 / f2)


def distance_modulus(d_pc):
    return 5.0 * math.log10(d_pc / 10.0)  # m - M: how much fainter a star looks than at 10 pc


def distance_from_modulus(mu):
    return 10.0 ** (mu / 5.0 + 1.0)


def parallax_distance_pc(parallax_arcsec):
    return 1.0 / parallax_arcsec  # small-angle definition of the parsec


def main():
    print(f"1 AU = {AU:.0f} m | 1 ly = {LY:.0f} m | 1 pc = {PC:.6e} m")
    print(f"1 pc = {PC / AU:.3f} AU = {PC / LY:.4f} ly | light from 1 AU takes {AU / C:.3f} s")
    print(f"5 mag brighter = x{flux_ratio(0, 5):.1f} flux | 1 mag = x{flux_ratio(0, 1):.4f}")
    print(f"flux x2 -> {mag_difference(2, 1):+.4f} mag")
    for d in (10, 100, 1000):
        print(f"star with M = 4.83 at {d:>4} pc: m = {4.83 + distance_modulus(d):6.2f} (distance modulus {distance_modulus(d):5.2f})")
    print(f"same star at 1 AU (the Sun): m = {4.83 + distance_modulus(AU / PC):.2f}")
    print(f"parallax 0.1 arcsec -> {parallax_distance_pc(0.1):.1f} pc; modulus 5.00 -> {distance_from_modulus(5.0):.1f} pc")


if __name__ == "__main__":
    main()

"""L100 Light and spectra: blackbody (Planck, Wien, Stefan-Boltzmann), Doppler shift and redshift.

python light.py
"""
import numpy as np

H = 6.62607015e-34      # Planck constant, J s (exact, SI 2019)
C = 299_792_458.0       # m/s (exact)
K = 1.380649e-23        # Boltzmann constant, J/K (exact)
B_WIEN = 2.897771955e-3  # Wien displacement constant, m K (CODATA)
SIGMA = 5.670374419e-8   # Stefan-Boltzmann constant, W m^-2 K^-4 (CODATA)
H_ALPHA = 656.28e-9      # hydrogen-alpha rest wavelength in air, m


def planck(wavelength_m, T):
    """Spectral radiance B_lambda(T) in W m^-2 sr^-1 m^-1."""
    x = H * C / (wavelength_m * K * T)
    return 2 * H * C**2 / wavelength_m**5 / np.expm1(x)  # expm1: accurate when x is small


def peak_wavelength(T, lo=50e-9, hi=50e-6, n=200_001):
    lam = np.geomspace(lo, hi, n)
    return lam[np.argmax(planck(lam, T))]  # numerical peak, to compare with Wien's law b / T


def total_flux(T):
    lam = np.geomspace(10e-9, 1e-2, 400_001)
    return np.pi * np.trapezoid(planck(lam, T), lam)  # pi * integral of B over wavelength = sigma T^4


def doppler_velocity(observed_m, rest_m):
    return C * (observed_m - rest_m) / rest_m  # non-relativistic: v = c * dlambda / lambda (+ = moving away)


def redshift(observed_m, rest_m):
    return observed_m / rest_m - 1.0


def relativistic_velocity(z):
    s = (1 + z) ** 2
    return C * (s - 1) / (s + 1)


def main():
    for name, T in (("Sun", 5772), ("Betelgeuse-like", 3600), ("Rigel-like", 12100)):
        print(f"{name:<16} T={T:>6} K  Wien b/T = {B_WIEN / T * 1e9:7.1f} nm  numerical peak = {peak_wavelength(T) * 1e9:7.1f} nm")
    print(f"Sun: pi * integral B = {total_flux(5772):.4e} W/m^2 vs sigma T^4 = {SIGMA * 5772**4:.4e} W/m^2")
    obs = 656.50e-9
    print(f"H-alpha observed at 656.50 nm: v = {doppler_velocity(obs, H_ALPHA) / 1000:+.1f} km/s (z = {redshift(obs, H_ALPHA):.6f})")
    for z in (0.001, 0.1, 1.0):
        print(f"z = {z:<5}: cz = {C * z / 1000:9.0f} km/s  relativistic Doppler v = {relativistic_velocity(z) / 1000:9.0f} km/s")


if __name__ == "__main__":
    main()
